const rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function maxhp(){return 130+p.level*14+p.vitality*25+(p.armor?.value||0)*3}function damage(){return 17+p.level*3+p.power*6+(p.weapon?.value||0)}
function say(s){$('toast').textContent=s;notice=3}function feed(s){log.unshift(s);log=log.slice(0,4);$('feed').innerHTML=log.join('<br>')}
function save(){try{localStorage.setItem('ashen-v1',JSON.stringify({p,floor}))}catch{}}
function newGame(type){p={x:0,y:0,level:1,xp:0,gold:0,points:0,power:type===0?2:0,vitality:type===1?2:0,focus:type===2?2:0,hp:160,mp:100,flasks:3,bag:[],weapon:null,armor:null,type};p.hp=maxhp();floor=1;started=true;dead=false;enterFloor();closePanel()}
