function equip(i){if(!Number.isInteger(i)||i<0||!p.bag[i])return false;let it=p.bag[i],old=p[it.slot],bag=p.bag.slice(),hp=p.hp;p.bag.splice(i,1);if(old)p.bag.push(old);p[it.slot]=it;p.hp=Math.min(p.hp,maxhp());if(save()===false){p.bag.splice(0,p.bag.length,...bag);p[it.slot]=old;p.hp=hp;say('保存できなかったため、装備変更を取り消しました');return false}panel('inventory');return true}
